it('caches dynamic validators by schema reference', async () => {
  const registry = new ToolRegistry();
  const schemas = [
    {type: 'object', required: ['location']},
    {type: 'object', required: ['unit']},
  ];
  let current = 0;
  registry.register(
    () => ({name: 'weather', description: 'Weather', inputSchema: schemas[current]}),
    async () => 'ok'
  );

  const compile = jest.spyOn(registry['validator'], 'compile');
  const first = await registry.execute('weather', {});
  const firstCompileCount = compile.mock.calls.length;
  await registry.execute('weather', {location: 'Paris'});
  current = 1;
  const second = await registry.execute('weather', {});
  await registry.execute('weather', {unit: 'C'});
  current = 0;
  await registry.execute('weather', {location: 'Paris'});
  expect({
    first: first.result,
    second: second.result,
    firstCompileCount,
    compileCount: compile.mock.calls.length,
  }).toEqual({
    first: expect.stringContaining('location'),
    second: expect.stringContaining('unit'),
    firstCompileCount: 1,
    compileCount: 2,
  });
});
